// Analyze_Symptom_Food — ассоциативный анализ «эпизоды симптома ↔ еда до них».
// Вход: symptom_id (из executeWorkflowTrigger). Читает Symptom_Log + Meals.
// НЕ доказательство — генератор кандидатов для элиминационного теста.
// Run Once for All Items.
// v2 (Батч 4 Гр.5): база = приёмы пищи в ТО ЖЕ время суток, что и pre-приёмы.
//   Эпизоды кучкуются по времени дня → pre смещён к ужину; сравнение со всеми приёмами
//   ложно поднимало «жиры/алкоголь/сахар» просто потому, что ужин ≠ завтрак.

function safeAll(n) { try { return $(n).all().map(i => i.json); } catch (e) { return []; } }
function num(v) {
  if (v == null || v === '') return null;
  const x = parseFloat(String(v).replace(',', '.'));
  return isNaN(x) ? null : x;
}
function round(x) { return x == null ? null : Math.round(x * 100) / 100; }
function ts(v) {
  let s = String(v == null ? '' : v).trim();
  if (!s) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) s += 'T12:00:00+10:00';           // дата без времени → полдень
  else s = s.replace(' ', 'T');
  if (!/[+Z]/.test(s.slice(10))) s += '+10:00';                        // без TZ → Владивосток
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d.getTime();
}

const symId = String(($json && $json.symptom_id) || ($('Analyze trigger').first().json.symptom_id) || '').trim();
const symRows = safeAll('Get Symptom_Log');
const mealRows = safeAll('Get Meals');

const WINDOW_H = 6;   // еда в пределах 6 ч ДО начала эпизода
const NUTR = ['Calories', 'Proteins', 'Carbs', 'Fats', 'Насыщенные жиры', 'Трансжиры',
  'Добавленный сахар', 'Кофеин', 'Алкоголь', 'Клетчатка', 'Холестерин', 'Натрий'];

if (!symId) return [{ json: { error: 'no symptom_id' } }];

const episodes = symRows
  .filter(r => String(r.Symptom_ID) === symId && ts(r.Date))
  .map(r => ({ at: ts(r.Date), severity: num(r.Severity), note: r.Note || r.Symptom || '' }))
  .sort((a, b) => a.at - b.at);

if (!episodes.length) {
  return [{ json: { symptom_id: symId, episodes: 0, note: 'Нет записанных эпизодов этого симптома в Symptom_Log.' } }];
}

const meals = mealRows
  .map(m => {
    const at = ts(m.Date);
    if (at == null) return null;
    const n = {}; NUTR.forEach(k => { n[k] = num(m[k]); });
    return { at, desc: String(m.Meal_description || ''), n };
  })
  .filter(Boolean)
  .sort((a, b) => a.at - b.at);

// разметка: попадает ли приём пищи в pre-окно хотя бы одного эпизода
const preIdx = new Set();
const perEpisodeHits = [];
for (const ep of episodes) {
  const hits = [];
  for (let i = 0; i < meals.length; i++) {
    if (meals[i].at <= ep.at && meals[i].at >= ep.at - WINDOW_H * 3600000) { preIdx.add(i); hits.push(i); }
  }
  perEpisodeHits.push(hits.length);
}
function vlHour(atMs) { return new Date(atMs + 10 * 3600000).getUTCHours(); }
function todBucket(atMs) {
  const h = vlHour(atMs);
  if (h >= 5 && h < 11) return 'утро';
  if (h >= 11 && h < 16) return 'день';
  if (h >= 16 && h < 23) return 'вечер';
  return 'ночь';
}
const pre = meals.filter((_, i) => preIdx.has(i));
const preBuckets = new Set(pre.map(m => todBucket(m.at)));
let base = meals.filter((_, i) => !preIdx.has(i) && preBuckets.has(todBucket(meals[i].at)));
let base_matched_by = 'то же время суток (' + [...preBuckets].join('/') + ')';
if (base.length < 3) {
  base = meals.filter((_, i) => !preIdx.has(i));
  base_matched_by = 'все приёмы — в то же время суток данных мало, возможна смещённость по времени дня';
}

if (pre.length < 2) {
  return [{ json: { symptom_id: symId, episodes: episodes.length, pre_meals: pre.length,
    note: 'Слишком мало приёмов пищи в окнах перед эпизодами (нет времени эпизодов в Symptom_Log?). Проси пациента отмечать время боли.' } }];
}

// ---- нутриенты: среднее на приём в pre vs base ----
function meanOf(arr, k) {
  const v = arr.map(m => m.n[k]).filter(x => x != null);
  return v.length ? v.reduce((s, x) => s + x, 0) / v.length : null;
}
const nutrient_candidates = NUTR.map(k => {
  const p = meanOf(pre, k), b = meanOf(base, k);
  if (p == null || b == null) return null;
  // база 0, а перед эпизодом есть — сильнейший сигнал (напр. кофеин/алкоголь/сахар)
  const ratio = b === 0 ? (p > 0 ? 99 : 1) : p / b;
  return { factor: k, pre_mean: round(p), base_mean: round(b), ratio: ratio === 99 ? '∞' : round(ratio),
    direction: (b === 0 ? p > 0 : ratio >= 1) ? 'выше/есть перед эпизодом' : 'ниже перед эпизодом',
    _abs: Math.abs(Math.log(ratio === 99 ? 20 : ratio || 1)) };
}).filter(x => x && (x.ratio === '∞' || x.ratio >= 1.4 || x.ratio <= 0.7))
  .sort((a, b) => b._abs - a._abs)
  .map(({ _abs, ...x }) => x);

// ---- продукты: частота слова в описаниях pre vs base ----
const STOP = new Set(['около', 'грамм', 'граммов', 'штук', 'штука', 'ложка', 'ложки', 'ложек', 'стакан',
  'порция', 'порции', 'вес', 'итого', 'примерно', 'свежий', 'свежая', 'свежие', 'сырой', 'сырая',
  'домашний', 'домашняя', 'кусок', 'кусочек', 'большой', 'маленький', 'средний', 'salad', 'штуки']);
function words(s) {
  return [...new Set((String(s).toLowerCase().match(/[а-яёa-z]{4,}/gi) || [])
    .map(w => w.replace(/(ый|ая|ое|ые|ой|ов|ам|ах|у|е|а|ы|и|я)$/, '')).filter(w => w.length >= 4 && !STOP.has(w)))];
}
const preW = {}, baseW = {};
pre.forEach(m => words(m.desc).forEach(w => preW[w] = (preW[w] || 0) + 1));
base.forEach(m => words(m.desc).forEach(w => baseW[w] = (baseW[w] || 0) + 1));
const food_candidates = Object.keys(preW).map(w => {
  const pf = preW[w] / pre.length;
  const bf = (baseW[w] || 0) / Math.max(base.length, 1);
  return { food: w, in_pre_meals: preW[w], pre_freq: round(pf), base_freq: round(bf),
    lift: bf > 0 ? round(pf / bf) : (pf > 0 ? 99 : 0) };
}).filter(x => x.in_pre_meals >= 2 && x.lift >= 1.8)
  .sort((a, b) => b.lift - a.lift).slice(0, 10);

const enough = episodes.length >= 4 && pre.length >= 4;

return [{
  json: {
    symptom_id: symId,
    episodes: episodes.length,
    episodes_with_meal_data: perEpisodeHits.filter(h => h > 0).length,
    pre_meals: pre.length,
    base_meals: base.length,
    base_matched_by,
    window_hours: WINDOW_H,
    nutrient_candidates: nutrient_candidates.slice(0, 8),
    food_candidates,
    confidence: enough ? 'предварительно' : 'очень низкая (мало эпизодов)',
    note: 'Ассоциативный анализ, НЕ доказательство причинности. Каждый кандидат проверяется элиминационным тестом (убрать на 2 недели → вернуть). При <4 эпизодах выводы почти случайны — нужно больше данных.',
  },
}];

